  ('e36-cooling-overhaul','e36-cooling-overhaul','s52','Cooling system overhaul','Engine','cooling','{"water pump","thermostat","radiator","expansion tank","overheating","coolant leak","fan clutch","11517527799","17111469179","cooling system"}',true,'2–6 hr',3);

-- 2) Guide content
insert into guides (id, content) values ('e36-cooling-overhaul', '{"id": "e36-cooling-overhaul", "title": "Cooling system overhaul", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same layout on every E36 six (325i/328i M50/M52) and the Z3 2.8/M — only the radiator part number changes", "category": "Engine", "kind": "repair", "heroId": "e36-cool-hero", "heroCap": "Front of the S52, looking down: radiator with the expansion tank clipped to its side, the fan shroud, the belt-driven fan on its viscous clutch, and behind it the water pump with the thermostat housing on the front of the head.", "glance": {"timeFirst": "2 hr refresh · 4–6 hr full", "timeRepeat": "1.5 hr · 3 hr", "difficulty": 3, "cost": "$150 refresh · $500–900 full", "risk": "Left-hand-thread fan nut · brittle 25-year-old plastic · an air pocket if you skip the bleed", "why": "This is the E36 job. The water pump, thermostat housing, radiator neck and expansion tank are all plastic or plastic-adjacent parts from the 1990s, and when one fails the S52 overheats fast enough to lift a head gasket before you''ve found a shoulder. Owners either replace the pump and thermostat every 60–80k or do everything at once at 100k. Both routes are in here.", "note": "Procedure agreed across Pelican, the Bentley manual (via owner transcriptions), and four owner write-ups. Torques are Bentley. Part numbers are the 1996–99 six-cylinder set; the M3 radiator is its own number."}, "lifespan": {"title": "When to expect it", "headline": ["Water pump and thermostat: 60,000–100,000 miles or 8–10 years", "Radiator, expansion tank and hoses: 100,000–150,000 miles or when the plastic yellows"], "earliest": "Any mileage if the pump still has the original plastic impeller", "detail": "Failures cluster around the plastic: the pump''s composite impeller sheds blades or the shaft bearing goes; the radiator''s plastic end-tank cracks at the upper hose neck; the expansion tank splits at a seam; the thermostat housing warps and weeps. Everything is date-stamped, so you can read what''s been done. If the pump is a metal-impeller unit with a date less than ten years old, a full overhaul may be premature.", "factors": ["Original plastic-impeller pump still fitted", "Track use or long idling in traffic", "Coolant never changed (acid eats the aluminium and plastics)", "Over-tightened plastic housings from a previous job"], "inspect": ["Every oil change: coolant level, colour, and a torch on the radiator neck and the thermostat housing seams for white crust", "Grab the fan blade cold and try to rock it — play means the pump bearing"], "confidence": {"level": "community", "n": 5, "note": "Interval is owner consensus, not a factory number. BMW lists no replacement interval for these parts."}}, "should": {"yesIf": ["Coolant level dropping with no obvious puddle", "White or blue crust at the radiator neck, thermostat housing or under the pump", "Temperature needle wandering past the 12 o''clock mark, or slow to warm", "Fan blade rocks on its hub, or a rumble that changes with revs from the front of the engine", "You bought the car, the records don''t show a pump, and it''s past 80k"], "codes": [], "notes": ["Two routes. Refresh = water pump, thermostat and housing, with the radiator left in. Full overhaul adds radiator, expansion tank, cap, hoses, fan clutch, sensors. Pick at the start; parts and steps adjust.", "The E36 M3 radiator is its own part (17111469179). The 328i unit doesn''t fit — check before you order a ''six-cylinder'' kit.", "Coolant: BMW blue (G48-type, silicate) mixed 50/50 with distilled water. The system holds about 10.5 litres; buy two gallons of concentrate to be safe.", {"text": "Aluminium housing: cures the warping, but you''re relying on a gasket surface you can''t inspect against a 25-year-old head. Clean the head face to bare metal.", "only": ["alu"]}], "confidence": {"level": "high", "n": 6, "note": "Symptom list and the two-route split agree across every source read."}}, "variants": {"questions": [{"question": "How far are you going?", "hint": "A refresh keeps the radiator in the car and swaps the parts that fail first. The full overhaul is the ''100k service'' — everything plastic comes out.", "options": [{"id": "refresh", "label": "Pump & thermostat refresh", "when": "Pump, thermostat, housing, belts. About 2 hours. Radiator stays."}, {"id": "full", "label": "Full overhaul", "when": "Adds radiator, expansion tank, cap, hoses, fan clutch, sensors. A Saturday."}]}, {"question": "Which thermostat housing?", "hint": "The factory housing is plastic and warps. An aluminium housing is the most common upgrade on this engine and costs about the same as a new plastic one.", "options": [{"id": "plastic", "label": "Factory plastic", "when": "Genuine or OEM plastic housing with a new gasket", "oeOnly": true}, {"id": "alu", "label": "Aluminium housing", "when": "Turner, ECS, Rein or similar; gasket or RTV depending on the maker"}]}]}, "parts": [{"tier": "oe", "name": "Water pump, metal impeller — Genuine BMW", "pn": "11517527799", "note": "Check the box: you want the metal impeller. Comes with the pump O-ring", "price": "$70–110", "links": [{"store": "FCP Euro", "url": "https://www.fcpeuro.com/BMW-parts/M3/Cooling-System/"}, {"store": "Pelican Parts", "url": "https://www.pelicanparts.com/byv-e36-m3-1996-3-2l/c-water-cooling-system_c-water-pump-thermostat-hoses"}]}, {"tier": "oem", "name": "Water pump — Saleri or Graf", "pn": "11517527799 (cross)", "note": "Same metal-impeller pump in a maker''s box", "price": "$45–70", "links": []}, {"tier": "oe", "name": "Thermostat, 88 °C", "pn": "11537511580", "note": "Some kits list 11537511083; both are the 88 °C unit. Comes with its O-ring", "price": "$20–35", "links": []}, {"tier": "oe", "name": "Thermostat housing, plastic + gasket", "pn": "11531722531 · gasket 11531740437", "note": "Buy the gasket even if the housing ''includes'' one", "price": "$25–45", "links": [], "only": ["plastic"]}, {"tier": "oem", "name": "Thermostat housing, aluminium", "pn": "Turner · ECS · Rein", "note": "Most ship with a gasket; Turner''s instructions call for a thin RTV bead", "price": "$40–80", "links": [{"store": "Turner Motorsport", "url": "https://www.turnermotorsport.com/BMW-E36-Parts/c-542-bmw-cooling-system-service"}], "only": ["alu"]}, {"tier": "oe", "name": "Radiator, E36 M3 — Genuine / Behr", "pn": "17111469179 (Behr 17111723784)", "note": "M3-specific. Move the two rubber feet from the old one", "price": "$200–320", "links": [{"store": "FCP Euro", "url": "https://www.fcpeuro.com/products/bmw-radiator-e36-17111469179"}], "only": ["full"]}, {"tier": "oe", "name": "Expansion tank + cap", "pn": "17111723520 · cap 17111742231", "note": "New cap every time; it sets system pressure", "price": "$50–80", "links": [], "only": ["full"]}, {"tier": "oe", "name": "Bleeder screw, brass", "pn": "replaces 17111712788", "note": "The plastic one strips. Brass is a $5 fix", "price": "$5–10", "links": [], "only": ["full"]}, {"tier": "oe", "name": "Upper & lower radiator hoses", "pn": "11531708499 · 11531726344", "note": "Six-cylinder E36 numbers — confirm against your VIN", "price": "$40–60", "links": [], "only": ["full"]}, {"tier": "oe", "name": "Fan clutch (Sachs / Behr) and fan blade", "pn": "11527505302 · blade 11521712058", "note": "Clutch if the fan freewheels hot or rumbles. Blade only if a fin is cracked", "price": "$80–120 · $60", "links": [], "only": ["full"]}, {"tier": "oe", "name": "Coolant level sensor · aux fan switch", "pn": "61311378320 · 61318361787", "note": "Cheap; both live on parts you''re removing", "price": "$25 · $20", "links": [], "only": ["full"]}, {"tier": "oe", "name": "BMW antifreeze (blue), 2 × 1 gal", "pn": "82141467704", "note": "Mix 50/50 with distilled water. Do not top up with orange or green", "price": "$25 each", "links": []}], "aftermarket": [{"name": "Stewart / EMP high-flow water pump", "note": "Billet housing, steel impeller, the pump everyone recommends for track cars. Overkill for a street car with a metal-impeller Genuine pump, but it''s a fit-and-forget part.", "price": "$250–300", "signal": "Track", "links": []}, {"name": "Aluminium thermostat housing", "note": "The upgrade almost everyone does. Turner has sold theirs for two decades; ECS and Rein make equivalents.", "price": "$40–80", "signal": "Common", "links": []}, {"name": "CSF / Fluidyne aluminium radiator", "note": "All-metal end tanks, so no more cracked necks. Drops in. Only worth it if you track the car or the plastic has failed twice.", "price": "$350–600", "signal": "Track", "links": []}, {"name": "Low-temperature thermostat (71 / 80 °C)", "note": "Popular, argued about. See disagreements — on a street S52 it costs you heater output and fuel trim for little gain.", "price": "$25–40", "signal": "Skip on street", "links": []}, {"name": "Electric fan conversion (SPAL kit)", "note": "Removes the mechanical fan and clutch. Frees a few hp and a lot of front-of-engine room; needs a controller and wiring. A project, not a service item.", "price": "$300–450", "signal": "Project", "links": []}], "tools": [{"name": "32 mm thin-profile fan-clutch wrench and a water-pump pulley holder (or a long screwdriver across two pulley bolts)"}, {"name": "10 mm and 13 mm sockets, 19 mm socket for the block drain, 16 mm socket on a breaker bar for the main belt tensioner, 8 mm hex for the A/C tensioner"}, {"name": "Two M6 × 75 mm bolts — to jack the old pump off its studs"}, {"name": "Hose-clamp pliers or a stubby 6 mm socket/driver for the worm clamps; flat-blade and Phillips screwdrivers"}, {"name": "Big drain pan (10+ litres), funnel, gasket scraper or plastic razor blade, brake cleaner, rags"}, {"name": "Torque wrench reading 10–40 Nm"}, {"name": "Ramps or stands — the front goes up for the bleed"}], "before": ["Engine stone cold. The system is at 2 bar and 90 °C when warm; the cap will scald you.", "Have the radio code if your head unit needs one, then disconnect the battery negative — you''ll be leaning over the alternator.", "Photograph the hose routing at the expansion tank and the shroud before anything comes off. Two of the small hoses look the same and aren''t.", {"text": "If your aluminium housing calls for RTV, read the cure time. Some want 24 hours before coolant — plan the job so the housing goes on the day before the fill.", "only": ["alu"]}], "chapters": [{"id": "strip", "title": "Drain & strip", "blurb": "Get the coolant out and the fan, shroud and belts off the front of the engine."}, {"id": "pump", "title": "Pump & thermostat", "blurb": "The two parts that actually fail. Same steps on both routes."}, {"id": "front", "title": "Radiator, tank & hoses", "blurb": "Full overhaul only — everything plastic in front of the engine."}, {"id": "fill", "title": "Fill & bleed", "blurb": "The step that decides whether the job worked."}], "steps": [{"n": 1, "chapter": "strip", "title": "Covers off, drain the radiator", "blocks": [{"t": "text", "b": "Remove the plastic radiator cover (four Phillips screws) and the alternator cooling duct (one 6 mm hose clamp). Set your pan under the passenger-side bottom corner of the radiator and back out the plastic drain screw a few turns — it''s a large Phillips head. Open the expansion tank cap and the bleeder screw beside it so the system can breathe. It''ll run for a while."}, {"t": "ill", "id": "e36-cool-drains", "cap": "Two drains: the radiator screw at the bottom corner, and the 19 mm block plug on the exhaust side, hiding behind the front O2 sensor."}, {"t": "note", "b": "Radiator alone gets you about two-thirds of the coolant out. On a refresh you can stop here — the pump sits above what''s left. On a full overhaul, drain the block too (next step)."}]}, {"n": 2, "chapter": "strip", "title": "Drain the block", "only": ["full"], "blocks": [{"t": "text", "b": "The block drain is a 19 mm plug low on the exhaust side, next to the front oxygen sensor — most owners unscrew the O2 sensor (22 mm) to get a socket on the plug, and tape over the sensor hole while the coolant runs. Wedge a wide funnel under the plug; it pours sideways. New crush washer on the way back in."}, {"t": "torque", "label": "Block drain plug (19 mm)", "nm": 25, "c": {"level": "community", "n": 2, "note": "Bentley value via owner transcriptions; not confirmed against a TIS page."}}]}, {"n": 3, "chapter": "strip", "title": "Fan and clutch off — left-hand thread", "blocks": [{"t": "warn", "b": "The fan clutch nut is a LEFT-hand thread. Standing at the front of the car, you loosen it by turning CLOCKWISE. Turning it the normal way tightens it — hard."}, {"t": "text", "b": "Slide the thin 32 mm wrench onto the clutch nut behind the fan and hold the pump pulley with the holder tool (or a long screwdriver braced across two pulley bolts). If it won''t budge, set the wrench at about 10 o''clock and give the free end a sharp rap with a mallet so it swings clockwise. Once it breaks free it spins off by hand; lift fan and clutch straight up and out of the shroud."}, {"t": "ill", "id": "e36-cool-fanclutch", "cap": "Viewed from the front: wrench on the clutch nut, holder on the pulley. Loosen clockwise. To refit, thread it on by hand and tap the wrench anticlockwise."}, {"t": "torque", "label": "Fan clutch to pump (32 mm, left-hand)", "nm": 40, "c": {"level": "community", "n": 3, "note": "Bentley 40 Nm. In practice a few sharp taps anticlockwise seats it; it self-tightens with rotation."}}]}, {"n": 4, "chapter": "strip", "title": "Shroud, expansion tank, belts", "blocks": [{"t": "text", "b": "Pop the two expanding rivets at the top of the fan shroud (push the centre pin, then pull). Unclip the coolant level sensor from the bottom of the expansion tank and unplug it. On a refresh, undo the two small hoses at the tank, tilt the shroud with the tank still on it back toward the engine and lift it clear. On a full overhaul the tank is coming off anyway — release its two hose clamps and the clips to the shroud, and set it aside."}, {"t": "text", "b": "Belts: 16 mm on the main tensioner pulley bolt, lever it clockwise to slacken and slip the belt off the alternator; 8 mm hex in the A/C tensioner to free the smaller belt. Note the routing — or see the belts guide, which is written for exactly this moment."}, {"t": "note", "b": "If either belt is more than three years old or gets coolant on it during the job, replace it. BMW''s own advice, and belts are cheap next to a pump."}]}, {"n": 5, "chapter": "strip", "title": "Hoses off, radiator out", "only": ["full"], "blocks": [{"t": "text", "b": "Unplug the auxiliary-fan temperature switch from the driver''s side of the radiator. Release the upper and lower radiator hoses at the radiator end (6 mm worm clamps) and the small hose from the tank to the radiator neck. The radiator now lifts straight up out of two rubber feet on the lower crossmember — nothing bolts it down. Wiggle it past the A/C condenser without dragging the fins."}, {"t": "text", "b": "Pull the two rubber feet off the old radiator and press them onto the new one now, before you forget. Move the aux-fan switch over too if you''re not replacing it (new O-ring)."}, {"t": "note", "b": "With the radiator out you have a clear view of the pump and thermostat housing. It''s why full-overhaul owners find the pump step easier than refresh owners do."}]}, {"n": 6, "chapter": "pump", "title": "Pulley off, pump out", "blocks": [{"t": "text", "b": "Four 10 mm bolts hold the pulley to the pump hub; the holder tool or the screwdriver trick keeps it from spinning. Behind it, four 10 mm nuts on M6 studs hold the pump to the timing case. The pump won''t pull off by hand — it''s an O-ring in a bore. Thread your two long M6 bolts into the two jacking holes in the pump flange and alternate turns; the pump walks out on the bolts."}, {"t": "ill", "id": "e36-cool-pump", "cap": "Pump face: four studs at the corners, two threaded jacking holes at 3 and 9 o''clock. Alternate half-turns on the jacking bolts so it comes out square."}, {"t": "text", "b": "Clean the bore with a plastic scraper and brake cleaner until it''s bright metal all the way round — old O-ring rubber left in the bore is the usual cause of a new pump weeping. Lightly coat the new O-ring with coolant (not grease), seat the pump by hand, and draw it home evenly with the four nuts."}, {"t": "torque", "label": "Water pump nuts (M6 ×4)", "nm": 10, "c": {"level": "high", "n": 4, "note": "Bentley 10 Nm for M6; matches Pelican, Doug''s Domain and two forum transcriptions."}}, {"t": "torque", "label": "Pump pulley bolts (M6 ×4, with washers)", "nm": 10, "c": {"level": "high", "n": 3, "note": "10 Nm, agreed. Washers must be under the heads — the factory bolts have them."}}]}, {"n": 7, "chapter": "pump", "title": "Thermostat and factory housing", "only": ["plastic"], "blocks": [{"t": "text", "b": "The housing is on the front of the head above the pump: three 10 mm bolts, plus the engine-lifting bracket that shares two 13 mm bolts with it (the longer bolt is the top one — mark it). Lift the housing away and the thermostat comes with it. Scrape the head face clean and dry."}, {"t": "text", "b": "Fit the new thermostat with the small vent hole or arrow at the top (12 o''clock) and its O-ring in the groove. If it goes in rotated, the system can''t bleed itself."}, {"t": "ill", "id": "e36-cool-thermostat", "cap": "Housing off the front of the head: thermostat with its vent at 12 o''clock, gasket, then the housing and the lifting bracket over the top two bolts."}, {"t": "text", "b": "Dry paper gasket between housing and head — no RTV, it''ll squeeze into the coolant. Snug the three bolts in a triangle pattern and stop at 10 Nm. Plastic flanges crack past that, and that crack is the leak you''ll be chasing in a month."}, {"t": "torque", "label": "Thermostat housing bolts (M6 ×3)", "nm": 10, "c": {"level": "high", "n": 4, "note": "Bentley 10 Nm. Every write-up warns about cracking the plastic here."}}, {"t": "torque", "label": "Engine lifting bracket (M8 ×2)", "nm": 22, "c": {"level": "community", "n": 2, "note": "Bentley 22 Nm via transcription."}}]}, {"n": 7, "chapter": "pump", "title": "Thermostat and aluminium housing", "only": ["alu"], "blocks": [{"t": "text", "b": "The housing is on the front of the head above the pump: three 10 mm bolts, plus the engine-lifting bracket that shares two 13 mm bolts with it (the longer bolt is the top one — mark it). Lift the housing away and the thermostat comes with it. Scrape the head face to bright, dry metal — an aluminium housing is only as good as the surface it sits on."}, {"t": "text", "b": "Fit the new thermostat with the small vent hole or arrow at the top (12 o''clock) and its O-ring in the groove. If it goes in rotated, the system can''t bleed itself."}, {"t": "ill", "id": "e36-cool-thermostat", "cap": "Housing off the front of the head: thermostat with its vent at 12 o''clock, gasket, then the housing and the lifting bracket over the top two bolts."}, {"t": "text", "b": "Follow the housing maker: most ship a gasket and want it dry; Turner''s sheet calls for a thin bead of coolant-safe RTV on the housing face instead of the gasket. If you use RTV, let it skin for ten minutes before bolting up and respect the cure time before filling. Never gasket and RTV together. Same 10 Nm — the housing won''t crack, but the head is aluminium too and its M6 threads strip."}, {"t": "torque", "label": "Thermostat housing bolts (M6 ×3)", "nm": 10, "c": {"level": "high", "n": 4, "note": "Bentley 10 Nm for M6 into the head, plastic or aluminium housing alike."}}, {"t": "torque", "label": "Engine lifting bracket (M8 ×2)", "nm": 22, "c": {"level": "community", "n": 2, "note": "Bentley 22 Nm via transcription."}}]}, {"n": 8, "chapter": "pump", "title": "Belts back on", "blocks": [{"t": "text", "b": "Main belt first: over the crank, alternator, power steering and pump pulleys, lever the tensioner clockwise with the 16 mm, slip the last run over the alternator, release. Then the A/C belt with the 8 mm hex. Check every rib sits in a groove on every pulley before you let go of the tensioner — a belt one groove off shreds in a minute."}, {"t": "note", "b": "On a refresh you can now skip straight to the fill chapter: refit shroud and tank in reverse (rivets, level sensor, the two hoses), then the fan."}]}, {"n": 9, "chapter": "front", "title": "Radiator, hoses and tank in", "only": ["full"], "blocks": [{"t": "text", "b": "Lower the new radiator onto its two rubber feet, aux-fan switch plugged in and its new O-ring seated. Lower hose on at the radiator end with the clamp positioned so you can reach it later. Upper hose on. New expansion tank clips to the shroud: the long hose runs along the bottom of the shroud to the block, the short one to the radiator neck on the driver''s side — match your photo."}, {"t": "ill", "id": "e36-cool-hoses", "cap": "The four rubber connections on the front: upper and lower radiator hoses, the tank-to-neck hose, and the long tank-to-block hose under the shroud."}, {"t": "text", "b": "Shroud back into its lower tabs, two new expanding rivets at the top, level sensor clicked into the bottom of the tank and plugged in. Fit the new brass bleeder screw loosely — it stays open for the fill."}]}, {"n": 10, "chapter": "front", "title": "Fan on", "only": ["full"], "blocks": [{"t": "text", "b": "Lower the fan into the shroud and thread the clutch nut onto the pump by hand — anticlockwise, remember. When it stops, put the 32 mm wrench on at about 11 o''clock and tap the end so it swings anticlockwise. Five to ten firm taps seats it; a fan clutch is one of the few fasteners that tightens itself in service."}, {"t": "text", "b": "Spin the fan by hand: it should turn with slight drag and clear the shroud all the way round. Refit the alternator duct and the radiator cover."}]}, {"n": 11, "chapter": "fill", "title": "Fill and bleed", "blocks": [{"t": "text", "b": "Front of the car up on ramps so the expansion tank is the highest point. Key to position 2 (ignition on, engine off), heater to full hot on the lowest fan speed — this opens the heater valve so the core fills. Cap off, bleeder screw open."}, {"t": "text", "b": "Pour the 50/50 mix in slowly at the tank. It gurgles as the block and heater core fill. Keep going until coolant comes out of the bleeder with no bubbles in it, then close the bleeder and fit the cap. That first fill is usually seven to eight litres of the 10.5-litre system."}, {"t": "ill", "id": "e36-cool-bleed", "cap": "Nose up, cap off, bleeder open, heater on hot. Fill until the bleeder runs solid, then cap and run to temperature."}, {"t": "text", "b": "Start it and hold 1,000–1,500 rpm until the needle sits in the middle and the thermostat opens (the upper hose goes hot). Idle it there for a few minutes with the heater blowing hot. Shut down, let it cool fully, and top the tank to the level float. Do that check again after the first drive."}, {"t": "warn", "b": "If the gauge climbs past 12 o''clock during the warm-up, or the heater blows cold while the engine is hot, there''s an air pocket. Shut it off, let it cool, and bleed again. Don''t drive it."}]}, {"n": 12, "chapter": "fill", "title": "Check for leaks and reset", "blocks": [{"t": "text", "b": "Reconnect the battery and enter the radio code. With the engine hot, torch every joint you touched: pump flange, housing seams, both radiator necks, the tank seams, every hose end. A clean paper towel wiped around each one finds a weep you can''t see."}, {"t": "text", "b": "Recheck the level cold after each of the first three drives. A small drop after the first drive is air working out; a drop after the third is a leak."}]}], "alsoReplace": [{"name": "Drive belts and tensioners", "why": "They''re off. Anything past three years or wet with coolant gets replaced — see the belts guide for the routing and tensioner torques."}, {"name": "Water pump pulley", "why": "Later cars have a composite pulley. If yours is plastic and yellowed, an aluminium one is $30 while the belt is off."}, {"name": "Heater and throttle-body ''spider'' hoses", "why": "The small hoses behind the engine and under the throttle body are the same age as everything you just replaced and are the next thing to burst. Cheap; an hour."}, {"name": "Coolant temperature sensors", "why": "Two of them in the thermostat housing area — one for the gauge, one for the DME. Both unplugged and exposed; new O-rings at minimum.", "only": ["full"]}, {"name": "Fan clutch", "why": "If you kept the old one: a clutch that freewheels when hot is the cause of a lot of ''my new cooling system still runs warm'' threads.", "only": ["refresh"]}], "check": {"tab": "Running warm?", "title": "What the gauge is telling you", "illId": "e36-cool-hero", "illCap": "Where each symptom points.", "rows": [{"see": "Needle creeps up in traffic, drops at speed", "means": "Fan clutch freewheeling, or the aux fan / its switch.", "do": "Hot engine off: fan should resist a hard spin. Aux fan should run with A/C on."}, {"see": "Needle past 12 o''clock at speed too", "means": "Thermostat stuck, pump impeller gone, or a radiator half full of scale.", "do": "Upper hose hot but lower cold at temp = thermostat. Pump: this guide."}, {"see": "Heater blows cold, gauge normal or high", "means": "Low coolant or an air pocket.", "do": "Level cold, then bleed again."}, {"see": "White crust on the radiator neck or housing seams", "means": "The plastic is weeping under pressure.", "do": "Replace the part; it won''t seal again."}, {"see": "Level drops, no crust anywhere, white exhaust on start", "means": "Head gasket or a cracked head — the thing this guide prevents.", "do": "Pressure test and a block test before you spend on cooling parts."}, {"see": "Rumble from the front that follows revs, fan wobbles", "means": "Pump bearing.", "do": "Stop driving it; the impeller is next."}], "c": {"level": "community", "n": 5, "note": "Diagnostic ladder from Pelican and owner threads; consistent."}}, "aftercare": ["Cold level check after each of the first three drives; top to the float.", "Look at the thermostat housing seam and the pump flange at 500 miles.", "Coolant change every three to four years from now — the blue coolant''s inhibitors are what protect the new aluminium."], "disagreements": [{"topic": "Low-temperature thermostat", "pos": "Track owners fit a 71 or 80 °C unit and report a cooler gauge.", "call": "Skip on a street car. The DME expects 88 °C for fuel trim, the heater suffers, and a healthy system holds the middle of the gauge on the stock stat anyway."}, {"topic": "RTV on the housing", "pos": "Some owners RTV every housing; others say never, gasket only.", "call": "Plastic housing: gasket only. Aluminium: do what the maker says, and never both gasket and RTV."}, {"topic": "Radiator out for a refresh?", "pos": "Pelican leaves it in; several owners pull it for room.", "call": "Leave it in unless you''re replacing it. Removing and refitting a 25-year-old radiator is how you crack its neck."}, {"topic": "Stewart pump on a street car", "pos": "''Best pump available'' versus ''a Genuine metal-impeller pump lasts 100k''.", "call": "Genuine is fine for the street. Stewart if you track it or never want to think about it again."}], "sources": ["Pelican Parts — BMW E36 Water Pump Replacement (tools, sequence, fan-clutch tips)", "Bentley E36 service manual torque values, via Bimmerfest and R3VLimited transcriptions", "Grassroots Motorsports forum — ''E36 Cooling System Overhaul Notes'' (full step list, fastener sizes, Bentley bleed procedure)", "Doug''s Domain (dvatp.com) — E36 Water Pump DIY (fan-clutch tightening, belt advice)", "Bimmerfest — ''E36 Cooling System 101'' parts list", "Turner Motorsport and FCP Euro E36 cooling overhaul kit listings (M3 radiator number, aluminium housing)", "Garage Built — E36 M3 Cooling System Rebuild (order of operations)"], "embeds": [{"id": "VW_uEfgvNaY", "note": "FCP Euro''s E36 M3 cooling overhaul, 2021 — radiator, pump, hoses, and a SPAL fan conversion you can ignore."}]}'::jsonb);

commit;
